Here's a complete TCP/IP server implementation in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address structure
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;  // Listen on all available interfaces
    address.sin_port = htons(PORT);

    // Bind the socket to the specified port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {  // 3 is the backlog (max pending connections)
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("TCP Server listening on port %d...\n", PORT);

    // Accept and handle client connections in a loop
    while (1) {
        printf("Waiting for incoming connections...\n");

        // Accept a new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            continue;
        }

        printf("Connection accepted from %s:%d\n", 
               inet_ntoa(address.sin_addr), ntohs(address.sin_port));

        // Handle client communication
        while (1) {
            memset(buffer, 0, BUFFER_SIZE);

            // Receive data from client
            int valread = read(new_socket, buffer, BUFFER_SIZE);
            if (valread <= 0) {
                if (valread == 0) {
                    printf("Client disconnected\n");
                } else {
                    perror("Read failed");
                }
                break;
            }

            printf("Client: %s", buffer);

            // Prepare response
            char response[BUFFER_SIZE];
            printf("Server: ");
            fgets(response, BUFFER_SIZE, stdin);

            // Remove newline from fgets
            response[strcspn(response, "\n")] = 0;

            // Send response back to client
            send(new_socket, response, strlen(response), 0);
            send(new_socket, "\n", 1, 0);
        }

        // Close the connection with this client
        close(new_socket);
        printf("Connection closed\n");
    }

    // Close server socket (this will never be reached in this infinite loop)
    close(server_fd);
    return 0;
}
```

## How to compile and run:

```bash
# Compile the code
gcc -o tcp_server tcp_server.c

# Run the server
./tcp_server
```

## Features of this TCP server:

1. **Socket Creation**: Creates a TCP socket using `socket()`
2. **Binding**: Binds to port 8080 on all network interfaces
3. **Listening**: Listens for incoming connections with a backlog of 3
4. **Connection Handling**: Accepts connections in a loop
5. **Message Processing**: Receives messages from clients and sends responses
6. **Error Handling**: Includes proper error checking and reporting
7. **Multiple Clients**: Can handle multiple clients sequentially

## To test the server:

You can use `telnet` or `nc` (netcat) to connect to the server:

```bash
telnet localhost 8080
```

Or write a simple client program to communicate with this server.

## Note:
- The server currently handles one client at a time in sequence
- For handling multiple concurrent clients, you would need to use threading or forking
- The server runs indefinitely until manually terminated (Ctrl+C)

